import{_ as t,o as d,a,b as r}from"./app.DKoEZOcr.js";const s=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"},{"text":"编译与部署","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/basic_process"},{"text":"多算子包组织","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/multi_operator_package"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/multi_operator_package.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/multi_operator_package.md","outlineHeaders":[{"level":2,"title":"默认建议","slug":"默认建议","link":"#默认建议"},{"level":2,"title":"单个算子包和多个算子包的区别","slug":"单个算子包和多个算子包的区别","link":"#单个算子包和多个算子包的区别"},{"level":2,"title":"适合拆成多个算子包的情况","slug":"适合拆成多个算子包的情况","link":"#适合拆成多个算子包的情况"},{"level":3,"title":"更新频率不同","slug":"更新频率不同","link":"#更新频率不同"},{"level":3,"title":"维护边界不同","slug":"维护边界不同","link":"#维护边界不同"},{"level":2,"title":"优先级配置","slug":"优先级配置","link":"#优先级配置"},{"level":2,"title":"相关文档","slug":"相关文档","link":"#相关文档"}],"lastUpdated":1787050286000}'),o={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/multi_operator_package.md"};function n(i,e,l,p,c,_){return d(),a("div",null,[...e[0]||(e[0]=[r('<div><article class="markdown-body"><h1>多算子包组织</h1><p>本文是扩展内容，介绍开发多个自定义算子时，如何决定这些算子的发布与部署方式——是全部放在一个算子包中，还是拆成多个算子包。</p><p>本文中的“算子包”指编译后生成的自定义算子安装包<code>custom_opp_*.run</code>。一个算子包可以包含一个或多个OpType，部署后通常位于<code>vendors/&lt;vendor_name&gt;</code>目录下。OpType是算子原型注册时的算子类型，例如<code>OP_ADD(AddCustom)</code>中的<code>AddCustom</code>。</p><p>本文主要讨论“多个算子如何拆分到一个或多个算子包”。如果需要了解多个算子如何编成一个算子包，需要如何组织多个算子的Host、核函数（Kernel）、Tiling文件，请参考<a href="./basic_process.html#%E7%BC%96%E8%AF%91%E7%BB%84%E7%BB%87">编译与部署基本流程</a>中的“按算子划分的目录结构”。</p><h2 id="默认建议">默认建议<a class="header-anchor" href="#默认建议">​</a></h2><p>默认建议放在同一个算子包中。只有在算子更新频率不同、需要独立编译部署，或由不同业务团队维护等情况时，才考虑拆成多个算子包。</p><table><thead><tr><th>场景</th><th>推荐策略</th><th>说明</th></tr></thead><tbody><tr><td>少量算子，由同一团队统一维护</td><td>单个算子包</td><td>编译、部署和验证流程最简单。</td></tr><tr><td>多个算子属于同一业务，一起发布和回归</td><td>单个算子包</td><td>减少算子包数量，避免额外优先级配置。</td></tr><tr><td>基础算子和实验算子更新频率不同</td><td>多个算子包</td><td>稳定包和实验包可以独立编译、部署和回退。</td></tr><tr><td>不同业务团队分别维护</td><td>多个算子包</td><td>每个团队维护独立包，通过优先级和部署路径集成。</td></tr></tbody></table><h2 id="单个算子包和多个算子包的区别">单个算子包和多个算子包的区别<a class="header-anchor" href="#单个算子包和多个算子包的区别">​</a></h2><table><thead><tr><th>对比项</th><th>单个算子包</th><th>多个算子包</th></tr></thead><tbody><tr><td>产物数量</td><td>一个<code>custom_opp_*.run</code></td><td>多个<code>custom_opp_*.run</code></td></tr><tr><td><code>vendor_name</code></td><td>通常只有一个。</td><td>每个包可使用不同<code>vendor_name</code>。</td></tr><tr><td>编译部署</td><td>一次编译、一次部署。</td><td>每个包独立编译和部署。</td></tr><tr><td>优先级配置</td><td>通常不需要。</td><td>同OpType冲突时需要配置。</td></tr><tr><td>适合场景</td><td>同一批算子共同发布。</td><td>算子生命周期、优先级或维护边界不同。</td></tr></tbody></table><p>单个算子包并不表示只能包含一个算子。它表示这些算子被打进同一个安装包、部署到同一个vendor目录，并作为一个整体发布。</p><h2 id="适合拆成多个算子包的情况">适合拆成多个算子包的情况<a class="header-anchor" href="#适合拆成多个算子包的情况">​</a></h2><h3 id="更新频率不同">更新频率不同<a class="header-anchor" href="#更新频率不同">​</a></h3><p>基础算子稳定后很少更新，而实验性算子或业务定制算子可能频繁迭代。将它们拆成不同算子包，可以降低每次修改的影响范围。</p><p>示例：</p><ul><li>基础算子包：稳定的通用算子，更新频率低；</li><li>实验算子包：仍在调优或验证的算子，更新频率高；</li><li>业务定制算子包：只服务某个业务场景，独立发布和回退。</li></ul><h3 id="维护边界不同">维护边界不同<a class="header-anchor" href="#维护边界不同">​</a></h3><p>不同业务团队维护的算子，通常不建议混在同一个算子包中。拆成多个算子包后，每个团队可以独立管理自己的源码、版本、部署节奏和问题回退。</p><h2 id="优先级配置">优先级配置<a class="header-anchor" href="#优先级配置">​</a></h2><p>多个自定义算子包共存时，只有包含相同OpType的算子才涉及优先级选择。不同OpType的算子不会因为<code>load_priority</code>互相覆盖。</p><p>不建议将同一OpType的多个版本作为常规部署方式长期共存。若确实需要临时共存并通过优先级选择版本，需要保证每个版本的Host侧库、核函数（Kernel）二进制、算子信息等产物完整一致，并完成目标场景回归验证。否则在某个高优先级版本的<code>.o</code>等产物不完备时，运行时可能混用低优先级版本的产物，导致版本误用或行为异常。</p><p>默认安装场景下，通过<code>opp/vendors/config.ini</code>中的<code>load_priority</code>配置各vendor的优先级。指定目录安装场景下，通过执行各算子包安装目录下的<code>set_env.bash</code>脚本顺序控制优先级。</p><p>详细配置方法请参考<a href="./basic_process.html#%E9%85%8D%E7%BD%AE%E8%87%AA%E5%AE%9A%E4%B9%89%E7%AE%97%E5%AD%90%E4%BC%98%E5%85%88%E7%BA%A7">配置自定义算子优先级</a>。</p><h2 id="相关文档">相关文档<a class="header-anchor" href="#相关文档">​</a></h2><ul><li><a href="./basic_process.html">编译与部署基本流程</a> — 编译配置、部署流程、包内目录组织方式。</li><li><a href="./dynamic_static_lib_compilation.html">算子动态库和静态库编译</a> — 以动态库或静态库形态输出算子。</li></ul></article></div>',1)])])}const g=t(o,[["render",n]]);export{s as __pageData,g as default};
